import { HANDS_COLS, HANDS_DARK, HANDS_LIGHT } from "./ascii-hands-data";

/**
 * ASCII hands from Michelangelo's "Creation of Adam" (public domain), generated by
 * scripts/make-ascii-hands.mjs. Two versions so the shading reads right on white and on black.
 * Sized in container units so the art always fills the width.
 */
export default function AsciiHands() {
  // monospace glyphs are about 0.6em wide, so this makes HANDS_COLS columns fill the width
  const style = { fontSize: `calc(100cqw / ${HANDS_COLS} / 0.6)` };
  const pre = "m-0 select-none font-mono leading-[1.15] text-ink";
  return (
    <div
      role="img"
      aria-label="ASCII art of the hands from Michelangelo's Creation of Adam"
      className="flex min-h-svh w-full items-center justify-center overflow-hidden px-4 [container-type:inline-size]"
    >
      <pre aria-hidden className={`${pre} dark:hidden`} style={style}>{HANDS_LIGHT.join("\n")}</pre>
      <pre aria-hidden className={`${pre} hidden dark:block`} style={style}>{HANDS_DARK.join("\n")}</pre>
    </div>
  );
}
